    // Basic terms
    Var { x: Var },
    Abs { x: Var, ty: Ty, body: Box<Tm> },
    App { t1: Box<Tm>, t2: Box<Tm> },
    Tru,
    Fls,
    Nat { n: nat },

    // Records
    RNil,                                                // Empty record {}
    RCons { label: Label, t: Box<Tm>, rest: Box<Tm> },  // {label = t, ...rest}
    RProj { t: Box<Tm>, label: Label },                  // t.label (field access)
}


