    recommends !matches!(t, Tree::E)
    decreases t
{
    match t {
        Tree::E => Tree::E,
        Tree::T { left, key, value, right } =>
            match *left {
                Tree::E => *right,
                _ => Tree::T {
                    left: Box::new(remove_min(*left)),
                    key,
                    value,
                    right,
                },
            }
    }
}

