    requires is_heap(h), i < h.data.len()
    ensures h.data[0] <= h.data[i as int]
    decreases i
{
    if i > 0 {
        let parent: nat = ((i - 1) / 2) as nat;
        assert(h.data[i as int] == h.data[i as int]);
        heap_root_le_node(h, parent);
    }
