pub open spec fn queue_normalize<T>(q: Queue<T>) -> Queue<T> {
    if q.front.len() == 0 && q.back.len() > 0 {
        Queue { front: seq_reverse(q.back), back: Seq::empty() }
    } else {
        q
    }
}

