        // T_True, T_False
        Tm::Tru => ty == Ty::TBool,
        Tm::Fls => ty == Ty::TBool,

        // T_Nat
        Tm::Nat { .. } => ty == Ty::TNat,

        // T_RNil: {} : {}
        Tm::RNil => ty == Ty::TRNil,

        // T_RCons: {l=t, ...rest} : {l:T, ...Rest} if t:T and rest:Rest
