    #[verifier::memoize]
    spec fn fib(x: nat) -> nat
        decreases x,
    {
        if x == 0 {
            0
        } else if x == 1 {
            1
        } else {
            fib((x - 1) as nat) + fib((x - 2) as nat)
        }
    }

    fn test() {
        //assert(fib(10) == 55);  // Fails without more fuel
