            let tracked visited = opt_visited.tracked_unwrap();
            map_visited_deps.insert(visited);
        }
        idx = idx + 1;
        assert forall|idx0: int| 0 <= idx0 && idx0 < idx implies ({
            let w = #[trigger] graph.edges@.index(v as int)@.index(idx0);
