#[derive(Structural, PartialEq, Eq)]
enum Color {
    White,  // 11
    Gray,  // 10
    Black,  // 01
    Undefined,  // 00
}

spec fn color_view(high: bool, low: bool) -> Color {
    if high {
        if low {
            Color::White
        } else {
            Color::Gray
        }
    } else {
        if low {
            Color::Black
        } else {
            Color::Undefined
        }
    }
}

spec fn bucket_view(bucket: u32) -> Seq<Color> {
    Seq::new(
        16,
        |i: int|
            color_view(
                get_bit!(bucket, add(mul(i as u32, 2), 1)),
                get_bit!(bucket, mul(i as u32, 2)),
            ),
