        let r1 = merge_sort(&mut v1);
        let r2 = merge_sort(&mut v2);
        proof {
            lemma_to_multiset_distributes_over_add(r1@, r2@);
        }
        let r = merge(&r1, &r2);
        r
    }
}

fn main() {
    let v = vec![9, 10, 4, 5, 1, 3];
    let v_sorted = merge_sort(&v);
